def bf(planet1, planet2):
    planets = ["Mercury", "Venus", "Earth", "Mars", "Jupiter", "Saturn", "Uranus", "Neptune"]
    orbits = {planet: index for index, planet in enumerate(planets)}

    if planet1.capitalize() not in planets or planet2.capitalize() not in planets:
        return ()

    start = min(orbits[planet1.capitalize()], orbits[planet2.capitalize()])
    end = max(orbits[planet1.capitalize()], orbits[planet2.capitalize()])

    selected_planets = [planet for planet in planets if start < orbits[planet] < end]
    sorted_planets = sorted(selected_planets, key=lambda x: orbits[x])

    return tuple(sorted_planets)

